{
  "selections": [
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '괜찮은 척하는 게 일부러 그런 게 아니라 안 할 수가 없다'고 한 발언은 '언제나 괜찮고 문제없는 모습만 보여줘야 한다'는 규칙이 자동적으로 작동하고 있음을 보여줌. 상담사의 '몸에 배어 있는 패턴'이라는 표현과 직접 연결."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "'안 할 수가 없다'는 말 뒤에는 진짜 감정이나 약한 모습을 드러내는 것 자체가 끔찍하게 느껴지는 태도가 깔려 있음. 상담사가 '알아차릴 때 어떤 기분인지'를 묻는 것은 이 태도에서 오는 감정을 탐색하기 위한 질문."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "'괜찮은 척'은 사람들 앞에서 밝고 문제없는 모습을 유지하며 힘든 감정을 혼자 삭히는 대처 전략의 직접적 표현. 상황 사례 3에서 수치심 이후 다음 날 더 밝고 괜찮은 척 행동하는 패턴과 동일."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'괜찮은 척' 패턴의 근본 동기는 '사람들이 진짜 나를 알면 떠날 것'이라는 핵심 신념. 연인이 '무슨 생각을 하는지 모르겠다'고 했을 때 명치가 답답해진 반응도 진짜 모습이 드러날까 봐 두려운 신념의 작동으로 해석 가능."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "'괜찮은 척을 알아차릴 때'의 기분은 결국 '진짜 나는 결함이 있다'는 수치심과 연결됨. 상담사의 질문은 이 결함/수치심 스키마가 활성화되는 순간의 정서를 확인하려는 것."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "'드러나면 사랑받지 못할 것'이라는 정의가 '괜찮은 척'을 멈출 수 없는 이유를 설명함. 상담사가 패턴의 자동성(안 할 수가 없다)을 짚으면서 그 아래 정서를 탐색하는 맥락."
    }
  ]
}

